package com.bank.scan;

import java.util.*;

// Known vulnerabilities: package -> severity. Can grow over time.
public class CveDatabase {
    private final Map<String, String> cves = new HashMap<>();

    public void addCve(String pkg, String severity) { cves.put(pkg, severity); }

    public Optional<String> severityFor(String pkg) {
        return Optional.ofNullable(cves.get(pkg));
    }
}
