package com.bank.scan;

import java.util.logging.Logger;

// Trivy/Grype role: inventory packages, check CVEs, fail on HIGH/CRITICAL.
public class ImageScanner {
    private static final Logger log = Logger.getLogger(ImageScanner.class.getName());
    private final CveDatabase db;

    public ImageScanner(CveDatabase db) { this.db = db; }

    public boolean passes(ImageSpec image) {
        log.info(() -> "Scanning " + image.getTag() + " (" + image.getPackages().size() + " packages)");
        int severe = 0;
        for (String pkg : image.getPackages()) {
            var sev = db.severityFor(pkg);
            if (sev.isPresent()) {
                String s = sev.get();
                if (s.equals("HIGH") || s.equals("CRITICAL")) {
                    severe++;
                    log.severe("  CVE in " + pkg + " severity=" + s);
                } else {
                    log.warning("  CVE in " + pkg + " severity=" + s + " (below gate)");
                }
            }
        }
        if (severe > 0) {
            log.severe("Scan FAILED: " + severe + " HIGH/CRITICAL findings -> block deploy");
            return false;
        }
        log.info("Scan PASSED: no HIGH/CRITICAL findings");
        return true;
    }
}
