package com.bank.scan;

import java.util.logging.Logger;

// Continuous scanning: re-check a stored image when new CVEs are published.
public class RegistryScanner {
    private static final Logger log = Logger.getLogger(RegistryScanner.class.getName());
    private final ImageScanner scanner;

    public RegistryScanner(ImageScanner scanner) { this.scanner = scanner; }

    public void rescan(ImageSpec stored) {
        log.info(() -> "Registry re-scan of stored image " + stored.getTag() + " after new CVE feed");
        if (!scanner.passes(stored)) {
            log.severe("Stored image " + stored.getTag() + " is NOW vulnerable -> raise alert, rebuild");
        }
    }
}
