package com.bank.scan;

import java.util.*;
import java.util.logging.Logger;

// Vault-like runtime source of secrets. Image never contains these.
public class SecretManager {
    private static final Logger log = Logger.getLogger(SecretManager.class.getName());
    private final Map<String, String> secrets = new HashMap<>();

    public void store(String name, String value) { secrets.put(name, value); }

    public String fetchAtRuntime(String name) {
        log.info(() -> "SecretManager issued '" + name + "' at container start (audited)");
        return secrets.get(name);
    }
}
