package com.bank.scan;

import java.util.logging.Logger;

// Refuses secrets in the image; mounts them at runtime from the manager.
public class SecretInjector {
    private static final Logger log = Logger.getLogger(SecretInjector.class.getName());
    private final SecretManager manager;

    public SecretInjector(SecretManager manager) { this.manager = manager; }

    // Reject any attempt to bake a secret into an image layer / ENV.
    public void rejectBakedSecret(String dockerfileLine) {
        String u = dockerfileLine.toUpperCase();
        if (u.startsWith("ENV") && (u.contains("PASSWORD") || u.contains("SECRET") || u.contains("KEY"))) {
            throw new SecurityException("Refusing baked secret in image: " + dockerfileLine);
        }
    }

    // Provide the secret at runtime as a mounted file (not an image layer).
    public void mountAtRuntime(String secretName) {
        String value = manager.fetchAtRuntime(secretName);
        log.info(() -> "Mounted '" + secretName + "' at /var/run/secrets/" + secretName
                + " (tmpfs, masked, not in image). value=***" + (value != null ? "" : "?"));
    }
}
