package com.bank.scan;

import java.util.List;
import java.util.logging.*;

public class ScanSecretsDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new ScanLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(ScanSecretsDemo.class.getName());

        CveDatabase db = new CveDatabase();
        db.addCve("jackson-2.9", "CRITICAL"); // vulnerable serialization lib
        ImageScanner scanner = new ImageScanner(db);

        log.info("=== Scan a VULNERABLE image (blocked) ===");
        scanner.passes(new ImageSpec("transfer-service:bad",
                List.of("temurin-21-jre", "jackson-2.9", "openssl-3.1")));

        log.info("=== Scan a CLEAN image (passes) ===");
        ImageSpec clean = new ImageSpec("transfer-service:good",
                List.of("temurin-21-jre", "jackson-2.17", "openssl-3.1"));
        scanner.passes(clean);

        log.info("=== Secrets: reject baked-in, mount at runtime ===");
        SecretManager manager = new SecretManager();
        manager.store("db-password", "S3cr3t!");
        SecretInjector injector = new SecretInjector(manager);
        try {
            injector.rejectBakedSecret("ENV DB_PASSWORD=S3cr3t!");
        } catch (SecurityException e) {
            log.severe(e.getMessage());
        }
        injector.mountAtRuntime("db-password");

        log.info("=== Continuous registry re-scan after new CVE ===");
        db.addCve("openssl-3.1", "HIGH"); // newly disclosed CVE
        new RegistryScanner(scanner).rescan(clean);
    }
}

